    "license": "CC BY-SA 4.0",
    "english": "The Yangtze is the longest river in Asia and the third-longest in the world, about 6,300 kilometres. It begins on the Qinghai-Tibet Plateau, runs through China's southwest, centre and east, and enters the sea at Shanghai. Together with the Yellow River it is called the mother river of Chinese culture. Rare animals such as the Chinese alligator live in it, and the Yangtze delta produces about a quarter of China's GDP.",
