    "english": "Noodles are a food made from flour and water, shaped into long strips and boiled before eating. China is their birthplace: in 2005 archaeologists found a 4,000-year-old bowl of noodles in Qinghai. Every region has its own kinds — hand-pulled noodles, knife-cut noodles, rice noodles — and there are countless ways to eat them. Because long noodles stand for long life, many people eat 'long-life noodles' on their birthday.",
