    "license": "CC BY-SA 4.0",
    "english": "West Lake lies west of the old city of Hangzhou in Zhejiang, with the urban area to its east and hills on the other three sides. Su Causeway and Bai Causeway cross the water, small islands dot the lake, and Leifeng Pagoda stands nearby. There is an old saying: 'Above there is heaven; below there are Suzhou and Hangzhou.' In 2011 West Lake's cultural landscape joined the UNESCO World Heritage list.",
