    "notes": [
      {
        "point": "不仅……也/还/而且……",
        "ex": "结婚以后，两个人不仅要互相理解，还要互相帮助。"
      },
      {
        "point": "从来（＋不/没）",
        "ex": "他从来不对我说假话。表示从过去到现在一直这样，常跟“不”连用。"
      },
      {
        "point": "刚",
        "ex": "他刚下班，现在正在回家的路上。表示动作发生在不久以前。"
      },
      {
        "point": "即使……也……",
        "ex": "即使不办酒席，我们的爱情也不会变。"
      },
      {
        "point": "（在）……上",
        "ex": "在生活上，他们互相帮助。／在结婚这个问题上，我们的想法一样。"
      }
    ],
    "compare": {
      "pair": "刚 — 刚才",
      "note": "“刚”是副词，放在动词前，表示动作完成不久：他刚走，你晚了一步。“刚才”是时间名词，指不久前的那段时间：他刚才还在休息，现在开始工作了。"
    },
    "sameChar": {
      "char": "感",
      "words": "感到 gǎndào · 感动 gǎndòng · 感冒 gǎnmào · 感兴趣 gǎn xìngqù"
    },
    "culture": {
      "title": "中国的情人节——七夕节",
      "body": "每年农历七月初七是七夕节，被称为中国的情人节。传说这一天，牛郎和织女会在鹊桥上见面。现在，很多人在这一天送花、送巧克力，表达自己的爱情。"
    },
