    "notes": [
      {
        "point": "正好",
        "ex": "我去的时候，他正好在家。表示两种情况碰巧一致。"
      },
      {
        "point": "差不多",
        "ex": "我们差不多十年没见面了。表示数量、程度相差很少。"
      },
      {
        "point": "尽管……却……",
        "ex": "尽管有的同学在国外，我们却一直保持着联系。"
      },
      {
        "point": "却",
        "ex": "大家都很高兴，他却一点儿也不高兴。表示转折，放在主语后。"
      },
      {
        "point": "而",
        "ex": "真正的朋友不是每天陪你玩儿的人，而是帮助你的人。"
      }
    ],
    "compare": {
      "pair": "差不多 — 几乎",
      "note": "“差不多”可以放在名词前表示数量相近：教室里差不多有五十个人；也可以作谓语：这两个词的意思差不多。“几乎”只是副词，表示“接近”：他几乎每天都来。"
    },
    "sameChar": {
      "char": "系",
      "words": "联系 liánxì · 关系 guānxi · 没关系 méi guānxi"
    },
    "culture": {
      "title": "在家靠父母，出门靠朋友",
      "body": "这句俗语的意思是：在家里，有困难可以找父母；离开家以后，就要靠朋友互相帮助了。它告诉我们朋友的重要性。"
    },
