    "english": "Mark caught a cold and his Chinese friend Xiaolin came to visit; Xiaoli and Xiaolin talk about a class reunion after almost ten years; Sun Yue and Wang Jing discuss what makes a true friend. Readings: everyone needs friends, and Mark's own experience of friendship in China. Grammar: 正好, 差不多, 尽管……却, 而, plus the saying 'at home rely on parents, away from home rely on friends'."
