    "notes": [
      {
        "point": "挺……的",
        "ex": "经理挺友好的。／他汉语说得挺好。口语中常用，程度比“很”轻一些。"
      },
      {
        "point": "本来",
        "ex": "本来我很紧张，后来慢慢放松了。表示原来的情况，常与“后来”相对。"
      },
      {
        "point": "另外",
        "ex": "他会英语；另外，他还会一点儿法语。表示“除此之外”。"
      },
      {
        "point": "首先……其次……",
        "ex": "首先，我做事认真；其次，我学习能力强。用于分条说明。"
      },
      {
        "point": "不管",
        "ex": "不管结果怎么样，你已经尽力了。／不管多忙，他都准时完成工作。"
      }
    ],
    "compare": {
      "pair": "另外 — 另",
      "note": "“另外”可以作插入语，表示除此之外：他会英语，另外还会法语；也可加“的”修饰名词：另外的办法。“另”不能单独用，后面要加数量词：另一个人、另一次机会。"
    },
    "sameChar": {
      "char": "时",
      "words": "时候 shíhou · 时间 shíjiān · 及时 jíshí · 平时 píngshí · 准时 zhǔnshí"
    },
    "culture": {
      "title": "中山装和旗袍",
      "body": "中山装和旗袍是中国传统服装。中山装简单、大方，以前男士在正式场合常穿；旗袍能表现出女性之美，现在不少人在结婚或参加重要活动的时候还会穿。"
    },
