    "notes": [
      {
        "point": "以为",
        "ex": "我以为这个星期做完就行，原来客户星期三就要。表示原来的想法与事实不一样。"
      },
      {
        "point": "原来",
        "ex": "原来是这么回事，我明白了。／他原来是老师，后来做了经理。"
      },
      {
        "point": "并（＋不/没）",
        "ex": "我并不同意你的看法。加强否定语气。"
      },
      {
        "point": "按照",
        "ex": "按照计划一步一步地做。／大家按照他说的去做。"
      },
      {
        "point": "甚至",
        "ex": "他忙得甚至连饭都没时间吃。表示更进一步。"
      }
    ],
    "compare": {
      "pair": "原来 — 本来",
      "note": "“原来”表示发现了以前不知道的情况：原来你是南方人啊！也可以表示“以前是”：他原来是老师。“本来”表示按原来的想法，常与“可是”连用：我本来想去，可是没时间。"
    },
    "sameChar": {
      "char": "法",
      "words": "办法 bànfǎ · 法律 fǎlǜ · 方法 fāngfǎ"
    },
    "culture": {
      "title": "授人以鱼不如授人以渔",
      "body": "这句话告诉我们：方法比结果更重要。好的老师不是直接给学生答案，而是教学生自己找到答案的办法；学会了方法，一辈子都能用。"
    },
