    "notes": [
      {
        "point": "肯定",
        "ex": "我敢肯定，他不知道这件事。／他肯定会喜欢。表示判断，语气比“可能”强。"
      },
      {
        "point": "再说",
        "ex": "这件衣服质量好；再说，价格也不贵。追加新的理由。"
      },
      {
        "point": "实际",
        "ex": "实际差远了。／实际上，他并不是老师。"
      },
      {
        "point": "对……来说",
        "ex": "对我来说，健康比钱更重要。表示从某人的角度。"
      },
      {
        "point": "尤其",
        "ex": "我喜欢吃水果，尤其是西瓜。表示更进一步突出。"
      }
    ],
    "compare": {
      "pair": "尤其 — 特别",
      "note": "“尤其”用来引出更突出的部分，有比较的意思，后面常跟“是”：大家都玩得很高兴，尤其是孩子们。“特别”还可以表示“与众不同”：这是一个特别的日子。"
    },
    "sameChar": {
      "char": "准",
      "words": "准时 zhǔnshí · 准备 zhǔnbèi · 标准 biāozhǔn"
    },
    "culture": {
      "title": "中国人的购物习惯",
      "body": "以前，中国人买东西喜欢去市场，买东西的时候习惯“讲价”。现在，网上购物越来越普遍，每年“双十一”，很多人半夜就在网上抢自己需要的东西。"
    },
