    "english": "Wang Jing buys a sofa and a shirt: comfort, quality and suitability — not price — are her standards. Dialogues in a furniture store, a mall and a supermarket. Readings: standards for buying clothes, and shopping online. Grammar: 肯定, 再说, 实际, 对……来说, 尤其. Same-character words with 准: 准时, 准备, 标准. Culture: Chinese shopping habits."
