    "notes": [
      {
        "point": "竟然",
        "ex": "那个箱子竟然要一千二！表示没想到，出乎意料。"
      },
      {
        "point": "倍",
        "ex": "现在的价格是以前的三倍。／我的书比他的多一倍。"
      },
      {
        "point": "值得",
        "ex": "这个箱子贵是贵，但是值得。／那部电影值得一看。"
      },
      {
        "point": "其中",
        "ex": "我们班有四十个学生，其中有十个是南方人。"
      },
      {
        "point": "（在）……下",
        "ex": "在质量好的情况下，贵一点儿也值得。／在朋友的帮助下，我完成了这个工作。"
      }
    ],
    "compare": {
      "pair": "值得 — 值",
      "note": "“值得”后面可以带动词或小句：这部电影值得一看；也能作谓语：这钱花得值得。“值”多用于口语，后面常带数量词：这本书值三十块。"
    },
