    "notes": [
      {
        "point": "估计",
        "ex": "估计是运动太少的原因。／我估计他今天不会来了。根据情况做出判断。"
      },
      {
        "point": "来不及",
        "ex": "别等来不及了才想起健康的重要。／时间来不及了，我们打车去吧。"
      },
      {
        "point": "离合词重叠（散散步）",
        "ex": "表示“做一会儿”，轻松的语气：散散步、打打太极拳、聊聊天、见见面。"
      },
      {
        "point": "要是",
        "ex": "你要是真心想戒烟，就得远离抽烟的朋友。"
      },
      {
        "point": "既……又/也/还……",
        "ex": "打太极既锻炼了身体，又呼吸了新鲜空气。"
      }
    ],
    "compare": {
      "pair": "估计 — 可能",
      "note": "“估计”是动词，根据情况做出判断，多用于口语：我估计他明天到。“可能”表示有可能，把握比“估计”小：他可能明天到，也可能后天到。"
    },
    "sameChar": {
      "char": "气",
      "words": "生气 shēngqì · 脾气 píqi · 空气 kōngqì · 气候 qìhòu"
    },
    "culture": {
      "title": "太极和太极拳",
      "body": "太极是中国古代的一种思想，讲究阴阳平衡。太极拳是一种传统运动，动作慢，适合各个年龄的人。早上，在中国的公园里，常常能看到很多人一起打太极拳。"
    },
