    "english": "Xiaolin catches colds from too little exercise; Xiaoyu tries to quit smoking; Xiaoli's neck and eyes hurt from sitting at the computer too long. Readings: your habits are the real doctor, and 75-year-old Grandpa Wang's taiji routine. Grammar: 估计, 来不及, verb reduplication (散散步), 要是, 既……又. Same-character words with 气: 生气, 脾气, 空气, 气候. Culture: taiji."
