    "notes": [
      {
        "point": "使",
        "ex": "堵车使大家的心情变坏。／这句话使我明白了一个道理。"
      },
      {
        "point": "只要……就……",
        "ex": "只要用心，美就在我们身边。／只要努力，就一定能学好汉语。"
      },
      {
        "point": "可不是（嘛）",
        "ex": "表示非常同意对方的话：“今天天真热！”“可不是嘛！”"
      },
      {
        "point": "因此",
        "ex": "他每天都锻炼，因此身体特别好。"
      },
      {
        "point": "往往",
        "ex": "周末的路上往往堵车。／春天往往多雨。表示某种规律。"
      }
    ],
    "compare": {
      "pair": "往往 — 经常",
      "note": "“往往”表示在一定条件下经常出现，是一种规律，不能用于将来的事：周末路上往往堵车。“经常”表示动作多次发生，可以用于将来：我以后要经常锻炼。"
    },
