    "notes": [
      {
        "point": "难道",
        "ex": "难道你就没想过放弃吗？加强反问的语气。"
      },
      {
        "point": "通过",
        "ex": "通过半年的坚持，她瘦了八公斤。／通过调查，他找到了问题。"
      },
      {
        "point": "可是",
        "ex": "这个办法好是好，可是太慢了。轻微转折。"
      },
      {
        "point": "结果",
        "ex": "我以为他不会来，结果他第一个到了。／三个月后，结果大不一样。"
      },
      {
        "point": "动词＋上",
        "ex": "请把门关上。／他很快穿上了大衣。表示动作完成并使物体到达一定位置。"
      }
    ],
    "compare": {
      "pair": "通过 — 经过",
      "note": "“通过”表示以某事物为方式或手段：通过调查发现问题；也表示从某处穿过：汽车从桥上通过。“经过”多表示一个过程或路过某处：经过三个月的努力；我每天经过这家店。"
    },
    "sameChar": {
      "char": "果",
      "words": "如果 rúguǒ · 结果 jiéguǒ · 效果 xiàoguǒ"
    },
    "culture": {
      "title": "成功的秘诀",
      "body": "有人问一位老演员成功的秘诀，他说：“我没有什么秘诀，如果非要说有，那就是别人休息的时候，我还在练。”可见，所谓秘诀，其实就是把简单的事情坚持下去。"
    },
