    "english": "Sun Yue lost eight kilos through half a year of persistence; Zhang Yuan's coffee shop lost money for six months until he found the problem; Wang Hong passed the graduate exam on her third try. Readings: there is sweat behind every success, and how Zhang Yuan turned his shop around. Grammar: 难道, 通过, 可是, 结果, verb+上 (关上, 穿上). Same-character words with 果: 如果, 结果, 效果. Culture: the secret of success."
